<div class="orth-section-intro"><div><h3>Seguimiento y evolución</h3><p>Cada control conserva el registro firmado. Las correcciones se realizan mediante adendas.</p></div><span class="orth-status"><?= count($controls) ?> controles</span></div>
<?php if($canWrite): ?><details class="panel orth-form-panel" id="orth-new-control"<?= !$controls?' open':'' ?>><summary><?= icon('plus',18) ?><span>Registrar una nueva evolución</span><small>Visita clínica individual</small></summary><form method="post" class="form-grid orth-panel-body orth-control-form" data-orth-dirty data-loading><?php $orthoFields('control',$case); ?><input type="hidden" name="request_key" value="<?= e(bin2hex(random_bytes(16))) ?>"><?php field('date','Fecha del control',date('Y-m-d'),'date',true,'max="'.date('Y-m-d').'"'); field('time','Hora',date('H:i'),'time'); ?><label>Profesional<input value="<?= e($case['professional'] ?? $case['dentist_name'] ?? '') ?>" readonly></label><?php field('phase','Fase del tratamiento','','text',false,'maxlength="160" list="orth-phases"'); ?><datalist id="orth-phases"><?php foreach($phases as $phase): ?><option value="<?= e($phase['stage_name'] ?? $phase['name'] ?? '') ?>"><?php endforeach; ?></datalist><?php if(!empty($ortho['appointments'])): ?><label class="full">Cita relacionada<select name="appointment_id"><option value="">Control sin cita vinculada</option><?php foreach($ortho['appointments'] as $appointment): ?><option value="<?= (int)($appointment['appointment_id'] ?? $appointment['id']) ?>"><?= local_date($appointment['starts_at'] ?? null) ?> · <?= e(label($appointment['status'])) ?></option><?php endforeach; ?></select></label><?php endif; area('observations','Observaciones clínicas','',true); area('procedures','Procedimientos realizados'); area('appliance_changes','Cambios en la aparatología'); area('incidents','Incidencias, molestias y hallazgos relevantes'); area('recommendations','Recomendaciones para el paciente'); field('next_control','Próximo control previsto','','date',false); ?><p class="orth-help">La fecha prevista permite identificar pendientes. Programa la cita en la agenda para reservar disponibilidad.</p><label class="orth-check full"><input type="checkbox" name="confirm_sign" value="1" required>Confirmo y firmo este registro clínico. Las correcciones posteriores conservarán el original.</label><button class="button full">Firmar y registrar evolución</button></form></details><?php endif; ?>
<section class="panel"><div class="orth-section-heading"><div><span class="orth-kicker">HISTORIA LONGITUDINAL</span><h3>Controles del paciente</h3></div></div><?php if(!$controls): $orthoEmpty('Aún no hay controles registrados','Registra una visita para comenzar la línea de tiempo del tratamiento.','chart'); else: ?><div class="orth-local-filters"><label>Desde<input type="date" data-orth-control-from></label><label>Hasta<input type="date" data-orth-control-to></label><label>Fase<input type="search" data-orth-control-phase placeholder="Buscar fase"></label><label>Profesional<input type="search" data-orth-control-professional placeholder="Buscar profesional"></label></div><div class="orth-timeline" data-orth-controls><?php foreach($controls as $entry): $entryId=(int)($entry['control_id'] ?? $entry['id']); $entryDate=substr($entry['occurred_at'] ?? '',0,10); ?><article class="orth-timeline-item" data-orth-control-date="<?= e($entryDate) ?>" data-orth-control-phase="<?= e($entry['phase'] ?? '') ?>" data-orth-control-professional="<?= e($entry['professional'] ?? '') ?>"><span class="orth-timeline-dot"></span><header><div><span class="orth-kicker"><?= local_date($entry['occurred_at'] ?? null) ?></span><h4><?= e($entry['phase'] ?: 'Control de ortodoncia') ?></h4><p><?= e($entry['professional'] ?? '') ?> · <?= e($entry['author'] ?? 'Registro clínico') ?></p></div><span class="orth-status">Firmado</span></header><div class="orth-control-details"><?php foreach(['observations'=>'Observaciones clínicas','procedures'=>'Procedimientos realizados','appliance_changes'=>'Cambios en la aparatología','incidents'=>'Incidencias y molestias','recommendations'=>'Recomendaciones'] as $key=>$title): $fallback=['observations'=>'notes','procedures'=>'procedures_done','recommendations'=>'instructions'][$key] ?? $key; if(!empty($entry[$key]) || !empty($entry[$fallback]))$orthoText($title,$entry[$key] ?? $entry[$fallback]); endforeach; ?></div><div class="orth-control-footer"><span><?= icon('calendar',15) ?> Próximo control: <?= $orthoDate($entry['next_control'] ?? null) ?></span><a class="orth-link" href="<?= e($caseLink('photos').'&control_id='.$entryId) ?>">Fotografías y estudios de esta visita</a></div><?php foreach($entry['addenda'] ?? [] as $addendum): ?><div class="orth-addendum"><strong>Adenda · <?= local_date($addendum['created_at'] ?? null) ?></strong><p><?= nl2br(e($addendum['notes'] ?? '')) ?></p><small>Motivo: <?= e($addendum['reason'] ?? '') ?> · <?= e($addendum['author'] ?? '') ?></small></div><?php endforeach; ?><?php if($canWrite): ?><details class="orth-addendum-form"><summary>Añadir una corrección o adenda</summary><form method="post" class="form-grid" data-orth-dirty data-loading><?php $orthoFields('addendum',$case); ?><input type="hidden" name="control_id" value="<?= $entryId ?>"><?php area('reason','Motivo de la corrección','',true); area('notes','Contenido de la adenda','',true); ?><button class="button secondary small">Guardar adenda</button></form></details><?php endif; ?></article><?php endforeach; ?></div><p class="orth-empty" data-orth-controls-empty hidden>No hay controles que coincidan con estos filtros.</p><?php endif; ?></section>
